package cli

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strconv"
	"strings"
	"sync"
)

// git_catfile_batch.go routes repeated object reads through one long-lived
// `git cat-file --batch` child per (gitDir, policy) instead of one `git
// cat-file` exec per blob. A cold export/distill on a ~1,000-checkpoint repo
// spawned ~5,000 git processes at ~30ms each (COR-2182); the same reads
// through one child are pipe round-trips.
//
// The child carries the exact policy of the per-exec path it replaces: the
// hardened git args every spawn gets, the repository filter-driver overrides,
// and GIT_NO_LAZY_FETCH=1 when the caller demanded a local-only read. Callers
// treat any infrastructure error as "fall back to the per-exec path", so a
// broken or killed child never changes behavior, only speed.
//
// Children exit on stdin EOF, which the OS delivers when this process exits.
// A long-lived parent (the MCP server) keeps at most one idle child per git
// dir and policy, which is bounded by the handful of repositories it serves.

// catFileBatchMaxBlobBytes bounds one blob read so a corrupt size header
// cannot drive the process out of memory. The per-exec path buffered whole
// blobs too; this is a guard against a nonsense header, not a content policy.
const catFileBatchMaxBlobBytes = 1 << 30

// errCatFileBatchMissing is git's definitive "object not found" answer. It is
// a real result, not an infrastructure failure: callers must NOT retry it on
// the per-exec path, which would answer the same thing one spawn later.
var errCatFileBatchMissing = errors.New("object missing")

type catFileBatchKey struct {
	gitDir    string
	localOnly bool
	check     bool
}

// catFileBatchProc is one child. Requests are strictly serialized under mu:
// one spec line written, one full record read, so the stream cannot desync
// across goroutines. Any read/parse irregularity marks the child broken and
// kills it; the registry replaces it on the next request.
type catFileBatchProc struct {
	mu     sync.Mutex
	cmd    *exec.Cmd
	in     io.WriteCloser
	out    *bufio.Reader
	broken bool
}

var (
	catFileBatchMu    sync.Mutex
	catFileBatchProcs = map[catFileBatchKey]*catFileBatchProc{}
)

func commandRunnerIsExec(runner CommandRunner) bool {
	switch runner.(type) {
	case ExecRunner, *ExecRunner:
		return true
	}
	return false
}

func catFileBatchProcFor(ctx context.Context, key catFileBatchKey) (*catFileBatchProc, error) {
	catFileBatchMu.Lock()
	defer catFileBatchMu.Unlock()
	if p, ok := catFileBatchProcs[key]; ok {
		return p, nil
	}
	mode := "--batch"
	if key.check {
		mode = "--batch-check"
	}
	args := hardenedGitArgs("cat-file", mode)
	overrides, err := repoFilterDriverOverrides(ctx, key.gitDir)
	if err != nil {
		return nil, err
	}
	var env map[string]string
	if key.localOnly {
		env = map[string]string{gitNoLazyFetchEnv: "1"}
	}
	// Not CommandContext: the child outlives any one caller's context on
	// purpose. It dies on stdin EOF when this process exits.
	cmd := exec.Command("git", args...)
	cmd.Dir = key.gitDir
	cmd.Env = gitConfigOverrideEnv(mergeCommandEnv(os.Environ(), env), overrides)
	in, err := cmd.StdinPipe()
	if err != nil {
		return nil, err
	}
	out, err := cmd.StdoutPipe()
	if err != nil {
		return nil, err
	}
	if err := cmd.Start(); err != nil {
		return nil, err
	}
	p := &catFileBatchProc{cmd: cmd, in: in, out: bufio.NewReader(out)}
	catFileBatchProcs[key] = p
	return p, nil
}

func catFileBatchDrop(key catFileBatchKey, p *catFileBatchProc) {
	catFileBatchMu.Lock()
	if catFileBatchProcs[key] == p {
		delete(catFileBatchProcs, key)
	}
	catFileBatchMu.Unlock()
}

func (p *catFileBatchProc) fail() {
	p.broken = true
	_ = p.in.Close()
	if p.cmd.Process != nil {
		_ = p.cmd.Process.Kill()
	}
	// Reap the child so a failed proc never lingers as a zombie.
	go func() { _ = p.cmd.Wait() }()
}

// request writes one spec and reads one record. body is nil in check mode.
// ponytail: no mid-read context cancellation — local object reads are pipe
// round-trips and the child dies with the parent; a hung git would require
// killing the child, which the broken path already does on the next error.
func (p *catFileBatchProc) request(ctx context.Context, spec string, withBody bool) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	if strings.ContainsAny(spec, "\n\r") {
		return nil, "", fmt.Errorf("git cat-file batch: spec contains a newline: %q", spec)
	}
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.broken {
		return nil, "", errors.New("git cat-file batch: process is broken")
	}
	fail := func(err error) ([]byte, string, error) {
		p.fail()
		return nil, "", err
	}
	if _, err := io.WriteString(p.in, spec+"\n"); err != nil {
		return fail(fmt.Errorf("git cat-file batch: write request: %w", err))
	}
	header, err := p.out.ReadString('\n')
	if err != nil {
		return fail(fmt.Errorf("git cat-file batch: read header: %w", err))
	}
	fields := strings.Fields(header)
	if len(fields) == 2 {
		// "<spec> missing" and friends ("ambiguous") are answers from a
		// healthy child, not failures.
		return nil, "", fmt.Errorf("git cat-file batch: %s %s: %w", spec, fields[1], errCatFileBatchMissing)
	}
	if len(fields) != 3 {
		return fail(fmt.Errorf("git cat-file batch: unexpected header %q for %s", strings.TrimSpace(header), spec))
	}
	objType := fields[1]
	size, err := strconv.ParseInt(fields[2], 10, 64)
	if err != nil || size < 0 {
		return fail(fmt.Errorf("git cat-file batch: unparseable size in header %q", strings.TrimSpace(header)))
	}
	if !withBody {
		return nil, objType, nil
	}
	if size > catFileBatchMaxBlobBytes {
		// Drain the record (content + trailing LF) to keep the stream in
		// sync, then refuse the read.
		if _, err := io.CopyN(io.Discard, p.out, size+1); err != nil {
			return fail(fmt.Errorf("git cat-file batch: drain oversized %s: %w", spec, err))
		}
		return nil, "", fmt.Errorf("git cat-file batch: %s is %d bytes, over the %d byte guard", spec, size, catFileBatchMaxBlobBytes)
	}
	body := make([]byte, size)
	if _, err := io.ReadFull(p.out, body); err != nil {
		return fail(fmt.Errorf("git cat-file batch: read %d-byte body for %s: %w", size, spec, err))
	}
	// Every record ends with one LF after the content.
	if trailer, err := p.out.ReadByte(); err != nil || trailer != '\n' {
		return fail(fmt.Errorf("git cat-file batch: record for %s not terminated by LF", spec))
	}
	return body, objType, nil
}

