package cli

import (
	"bytes"
	"encoding/json"
	"strings"
)

// distill_preprocess.go is the streaming transcript preprocessor. It replaces
// a map[string]any decode of every JSONL record with a typed decode that names
// only the handful of fields the conversation extractor reads; the megabytes
// of tool output per record are scanned past by the decoder without ever being
// materialized as Go values. On the full corpus this removed ~5s of CPU and
// most of the GC churn from a cold distill while producing BYTE-IDENTICAL
// output to the previous implementation — identical output is a hard
// requirement, because session fingerprints hash this text and any drift would
// re-distill every cached session (see distillPreprocessingVersion for the
// escape hatch when a semantic change is intended).
//
// The reference map-based implementation lives in distill_preprocess_test.go
// and a differential test holds the two equal across every dialect.

// rawTranscriptRecord names the only top-level fields the extractor reads.
// Every field is a RawMessage so a record whose field has an unexpected type
// decodes exactly like the map path did (the value is simply not a string /
// not an object when interpreted), instead of failing the whole line into
// passthrough.
type rawTranscriptRecord struct {
	Type    json.RawMessage `json:"type"`
	Message json.RawMessage `json:"message"`
	Payload json.RawMessage `json:"payload"`
	Content json.RawMessage `json:"content"`
}

// rawEnvelope covers the nested shapes: event_msg/response_item payloads and
// claude-code/pi message wrappers.
type rawEnvelope struct {
	Type             json.RawMessage `json:"type"`
	Role             json.RawMessage `json:"role"`
	Message          json.RawMessage `json:"message"`
	LastAgentMessage json.RawMessage `json:"last_agent_message"`
	Content          json.RawMessage `json:"content"`
}

// rawTextBlock is one entry of a message "content" array.
type rawTextBlock struct {
	Type       json.RawMessage `json:"type"`
	Text       json.RawMessage `json:"text"`
	InputText  json.RawMessage `json:"input_text"`
	OutputText json.RawMessage `json:"output_text"`
	Content    json.RawMessage `json:"content"`
}

// rawJSONString mirrors jsonString over a decoded value: the string content
// when the JSON value is a string, "" for everything else (absent, null,
// number, object, array).
func rawJSONString(raw json.RawMessage) string {
	if len(raw) == 0 || raw[0] != '"' {
		return ""
	}
	var s string
	if json.Unmarshal(raw, &s) != nil {
		return ""
	}
	return s
}

// rawFirstNonEmptyString mirrors firstNonEmptyString: the first value that is
// a JSON string with non-whitespace content, returned untrimmed.
func rawFirstNonEmptyString(raws ...json.RawMessage) string {
	for _, raw := range raws {
		if text := rawJSONString(raw); strings.TrimSpace(text) != "" {
			return text
		}
	}
	return ""
}

// rawEnvelopeOf mirrors jsonMap: the decoded envelope when the value is a JSON
// object, a zero envelope for everything else (absent, null, string, array).
func rawEnvelopeOf(raw json.RawMessage) rawEnvelope {
	var env rawEnvelope
	if len(raw) == 0 || raw[0] != '{' {
		return rawEnvelope{}
	}
	if json.Unmarshal(raw, &env) != nil {
		return rawEnvelope{}
	}
	return env
}

// rawTextBlocks mirrors distillTextBlocks over a raw content value: a plain
// string passes through, an array keeps the text of non-tool blocks, anything
// else is "".
func rawTextBlocks(content json.RawMessage) string {
	if len(content) == 0 {
		return ""
	}
	if content[0] == '"' {
		return rawJSONString(content)
	}
	if content[0] != '[' {
		return ""
	}
	var items []json.RawMessage
	if json.Unmarshal(content, &items) != nil {
		return ""
	}
	var parts []string
	for _, item := range items {
		if len(item) == 0 || item[0] != '{' {
			continue // mirrors jsonMap(item) == nil → len 0 → skip
		}
		var block rawTextBlock
		if json.Unmarshal(item, &block) != nil {
			continue
		}
		switch rawJSONString(block.Type) {
		case "tool_use", "tool_result":
			continue // tool call / tool output
		default:
			if text := rawFirstNonEmptyString(block.Text, block.InputText, block.OutputText, block.Content); text != "" {
				parts = append(parts, text)
			}
		}
	}
	return strings.Join(parts, " ")
}

// rawConversationText mirrors distillConversationText (the reference copy in
// distill_preprocess_test.go) over one decoded record.
func rawConversationText(rec rawTranscriptRecord) string {
	switch rawJSONString(rec.Type) {
	case "agent_message":
		return rawJSONString(rec.Message)
	case "event_msg":
		payload := rawEnvelopeOf(rec.Payload)
		switch rawJSONString(payload.Type) {
		case "agent_message", "user_message":
			return rawJSONString(payload.Message)
		case "task_complete":
			return rawJSONString(payload.LastAgentMessage)
		}
		return "" // task_started, exec_command_end, patch_apply_end, ...
	case "response_item":
		payload := rawEnvelopeOf(rec.Payload)
		if rawJSONString(payload.Type) != "message" {
			return "" // function_call, custom_tool_call, function_call_output, reasoning
		}
		if role := rawJSONString(payload.Role); role != "assistant" && role != "user" {
			return ""
		}
		return rawTextBlocks(payload.Content)
	case "assistant", "user":
		// Presence of "message" (even null) selects the nested shape, exactly
		// like the map path's two-value key lookup did.
		if rec.Message != nil {
			return rawTextBlocks(rawEnvelopeOf(rec.Message).Content)
		}
		return rawTextBlocks(rec.Content)
	case "message":
		payload := rawEnvelopeOf(rec.Message)
		if role := rawJSONString(payload.Role); role != "assistant" && role != "user" {
			return "" // toolResult, ...
		}
		return rawTextBlocks(payload.Content)
	case "session_meta", "turn_context", "permission-mode", "progress":
		return ""
	default:
		return rawJSONString(rec.Message)
	}
}

// preprocessTranscriptLine transforms one JSONL line exactly as the legacy
// per-line logic did: blank stays blank, non-JSON-object lines pass through
// unchanged, and a decoded record collapses to its whitespace-normalized
// conversation text.
func preprocessTranscriptLine(line []byte) string {
	if len(bytes.TrimSpace(line)) == 0 {
		return ""
	}
	var rec rawTranscriptRecord
	if err := json.Unmarshal(line, &rec); err != nil {
		return string(line) // not a JSON object; leave the line as-is
	}
	return strings.Join(strings.Fields(rawConversationText(rec)), " ")
}

// preprocessTranscriptForDistillBytes is the streaming core behind
// preprocessTranscriptForDistill: one pass over the raw bytes, line slices
// taken zero-copy, no whole-file string or line-slice materialization.
func preprocessTranscriptForDistillBytes(data []byte) string {
	if doc, ok := distillDocumentConversation(string(data)); ok {
		return doc
	}
	var b strings.Builder
	// Stripped output is a fraction of the input; start small and let the
	// builder grow instead of reserving input-sized memory.
	b.Grow(min(len(data)/16+64, 1<<20))
	rest := data
	for first := true; ; first = false {
		if !first {
			b.WriteByte('\n')
		}
		idx := bytes.IndexByte(rest, '\n')
		line := rest
		if idx >= 0 {
			line = rest[:idx]
			rest = rest[idx+1:]
		}
		b.WriteString(preprocessTranscriptLine(line))
		if idx < 0 {
			return b.String()
		}
	}
}

